import React, { useEffect, useState } from 'react';
import api from '../utils/api';

const RevenueTable = ({ data }) => {
    return (
        <div>
            <h2>Revenue Per Hour by Aircraft</h2>
            <table>
                <thead>
                    <tr>
                        <th>Aircraft</th>
                        <th>Revenue Per Hour ($)</th>
                    </tr>
                </thead>
                <tbody>
                    {Object.entries(data).map(([aircraft, revenue]) => (
                        <tr key={aircraft}>
                            <td>{aircraft}</td>
                            <td>{revenue.toFixed(2)}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

const ChartComponent = () => {
    const [revenuePerHour, setRevenuePerHour] = useState({});
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                console.log('Data received:', result.data); // Log the data received
                processRevenueData(result.data.invoices, result.data.loggedFlights);
            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        const processRevenueData = (invoices, loggedFlights) => {
            const filteredInvoices = invoices.filter(invoice => invoice.Status === 'Invoiced');
            const aircraftRevenue = {};
            const aircraftHours = {};

            filteredInvoices.forEach(invoice => {
                if (aircraftRevenue[invoice.Aircraft]) {
                    aircraftRevenue[invoice.Aircraft] += parseFloat(invoice.Price);
                } else {
                    aircraftRevenue[invoice.Aircraft] = parseFloat(invoice.Price);
                }
            });

            loggedFlights.forEach(flight => {
                if (aircraftRevenue[flight.Aircraft]) { // Only count flights for invoiced aircrafts
                    if (aircraftHours[flight.Aircraft]) {
                        aircraftHours[flight.Aircraft] += parseFloat(flight['Flight hrs']);
                    } else {
                        aircraftHours[flight.Aircraft] = parseFloat(flight['Flight hrs']);
                    }
                }
            });

            const revenuePerHourData = {};
            Object.keys(aircraftRevenue).forEach(aircraft => {
                if (aircraftHours[aircraft]) {
                    revenuePerHourData[aircraft] = aircraftRevenue[aircraft] / aircraftHours[aircraft];
                } else {
                    revenuePerHourData[aircraft] = 0; // Handle case where there are no flight hours
                }
            });

            setRevenuePerHour(revenuePerHourData);
        };

        fetchData();
    }, []);

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div>
            <h1>Aircraft Revenue Analysis</h1>
            <RevenueTable data={revenuePerHour} />
        </div>
    );
};

export default ChartComponent;
